/**
 * Injects mapStats into player objects.
 * Call after TEAMS is loaded.
 */
function injectPlayerMapStats() {
  TEAMS.forEach(team => {
    team.players.forEach(player => {
      if (PLAYER_MAP_STATS[player.nick]) {
        player.mapStats = PLAYER_MAP_STATS[player.nick];
      } else {
        player.mapStats = generateDefaultMapStats(player);
      }
    });
  });
  console.log("✓ Map stats injected (HLTV data)");
}

function generateDefaultMapStats(player) {
  const firepower = player.firepower || 75;
  const baseFactor = (firepower - 50) / 50;
  const maps = ["Mirage", "Inferno", "Nuke", "Dust2", "Ancient", "Anubis", "Train"];
  const mapStats = {};
  maps.forEach(map => {
    const variance = (Math.random() - 0.5) * 0.2;
    const ratingBase = 1.0 + (baseFactor * 0.3) + variance;
    mapStats[map] = {
      rating: Math.max(0.6, Math.min(1.8, ratingBase)),
      impact: Math.max(0.8, Math.min(1.8, ratingBase + 0.05)),
      adr: Math.round(65 + (baseFactor * 15) + (Math.random() - 0.5) * 10),
      kpr: Math.round((0.58 + (baseFactor * 0.14) + (Math.random() - 0.5) * 0.06) * 100) / 100,
      mapsPlayed: Math.floor(10 + (Math.random() * 10)),
      winRate: Math.min(1.0, Math.max(0.45, 0.5 + (baseFactor * 0.15) + (Math.random() - 0.5) * 0.1))
    };
  });
  return mapStats;
}

document.addEventListener("DOMContentLoaded", () => {
  if (typeof TEAMS !== "undefined") {
    injectPlayerMapStats();
  }
});
